62-// deduped and sorted. Async because task discovery is; pure otherwise.
63-export async function declaredSecrets(root, config) {
64-  const { discoverTasks } = await import('./discover.mjs');
65-  const { tasks } = await discoverTasks(root, config);
66-  return [...new Set(tasks.flatMap((t) => t.decl?.required_secrets ?? []))].sort();
67-}
