164-  const packs = await loadPacks({ localRoot: root });
165-  const byId = new Map(packs.map((p) => [p.id, p]));
166-  const entries = [];
167-  for (const entry of resolveDeclaredPacks(config.packs ?? [], packs)) {
168-    const pack = byId.get(packEntryId(entry));
169:    if (!pack || typeof pack.badge !== 'string' || !pack.badge) continue;
170:    const path = relative(root, join(pack.dir, pack.badge)).split('\\').join('/');
171-    if (existsSync(join(root, path))) entries.push({ id: pack.id, path });
172-  }
173-  return entries;
174-}
