179-/ Write the row into the repo's README: replacing the delimited block where one
180:// exists, otherwise introducing it just under the title (a README's badges belong
181-// where a reader looks first) or at the very top when there is no heading.
182-// Returns true when the file was written. No README, or nothing to show, means
183-// nothing to do — this converge never creates a README.
184-export function convergeBadgeRow(root, entries) {
185-  const path = join(root, README);
186-  if (!existsSync(path) || !entries.length) return false;
187-  const text = readFileSync(path, 'utf8');
188-  const row = renderBadgeRow(entries);
189-  if (BADGE_ROW_RE.test(text)) {
190-    const next = text.replace(BADGE_ROW_RE, row);
191-    if (next === text) return false;
192-    writeFileSync(path, next);
193-    return true;
194-  }
195-  const lines = text.split('\n');
196-  const title = lines.findIndex((l) => l.startsWith('# '));
197-  const at = title === -1 ? 0 : title + 1;
198-  lines.splice(at, 0, ...(at === 0 ? [row, ''] : ['', row]));
199-  writeFileSync(path, lines.join('\n'));
200-  return true;
201-}
