203-// Converge every wiring surface, returning a flat summary of what changed (empty
204-// when the repo was already converged). `stubText` is the vendored scheduler stub.
205-export async function convergeWiring(root, fullName, stubText, secretNames = []) {
206-  const changed = [];
207-  if (convergeSchedulerWorkflow(root, fullName, stubText, secretNames)) changed.push(SCHEDULER_WORKFLOW);
208-  const hooks = ensureHooks(root);
209-  for (const h of hooks.added) changed.push(`hook:${h}`);
210-  if (removeRetiredCorpusImport(root)) changed.push(`removed retired ${CLAUDE_MD} corpus import`);
211:  if (ensureBadgeSetting(root)) changed.push(`${CHECKS_PATH} badges`);
212-  const config = await repoConfig(root);
213-  / 'off' is the repo's answer, and it means BOTH halves: stop updating the row,
214-  // and stop re-adding one the repo has deleted.
215:  if (config.badges?.readme !== 'off' && convergeBadgeRow(root, await badgeRowEntries(root, config))) changed.push(`${README} pack row`);
216-  return { changed, ...(hooks.error ? { error: hooks.error } : {}) };
217-}
