219-/ CLI: `node converge-wiring.mjs [owner/repo]` — converge THIS repo's wiring. The
220-// full name comes from argv or GITHUB_REPOSITORY/CLAUDINITE_REPO; the scheduler
221-// stub from the vendored mount. This is the single surface bootstrap (Part 6) and
222-// baselining both invoke, so the wiring set is defined once, here.
223-async function main() {
224-  const fullName = process.argv[2] || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
225-  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
226-  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
227-  const stubPath = join(root, '.claudinite/shared/engine/scheduler/stubs/claudinite-scheduler.yml');
228-  if (!existsSync(stubPath)) { console.error(`converge-wiring: vendored stub not found at ${stubPath}`); process.exit(1); }
229-  const secretNames = await declaredSecrets(root, await repoConfig(root));
230-  const { changed, error } = await convergeWiring(root, fullName, readFileSync(stubPath, 'utf8'), secretNames);
231-  if (error) console.log(`! ${error}`);
232-  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
233-}
