  writeFileSync(join(root, CHECKS_PATH), '{\n  "badges": { "readme": "off" }\n}\n');
  assert.equal(ensureBadgeSetting(root), false);
  assert.equal(JSON.parse(readFileSync(join(root, CHECKS_PATH), 'utf8')).badges.readme, 'off');
});

